def is_point_on_segment(p, a, b):
    if a == b:
        return p == a
    xs = {a[0], b[0], p[0]}
    ys = {a[1], b[1], p[1]}
    if len(xs) == 3 or len(ys) == 3:
        return False
    return p == a or p == b
