def is_point_on_segment(p, a, b):
    px, py = p
    ax, ay = a
    bx, by = b
    # equals for the endpoints
    if (px, py) == (ax, ay) or (px, py) == (bx, by):
        return True
    # vertical segment
    if ax == bx:
        return px == ax and min(ay, by) <= py <= max(ay, by)
    # horizontal segment
    if ay == by:
        return py == ay and min(ax, bx) <= px <= max(ax, bx)
    # neither vertical nor horizontal: not collinear with the segment
    return False
```

