def is_convex_polygon(points):
    n = len(points)
    for i in range(n):
        a = points[(i - 1) % n]
        b = points[i]
        c = points[(i + 1) % n]
        ab = (b[0] - a[0], b[1] - a[1])
        bc = (c[0] - b[0], c[1] - b[1])
        cross = ab[0] * bc[1] - ab[1] * bc[0]
        if cross == 0:
            return False
        if i == 2:
            sign = 1 if cross > 0 else -1
        elif sign * cross < 0:
            return False
        elif sign * cross == 0:
            return False
    return True
```

