def count_points_in_circle(points, center, radius):
    cx, cy = center
    count = 0
    for x, y in points:
        if (x == cx and y == cy) or (x == cx and y > cy) or (x > cx and y == cy) or (x - cx < radius and y - cy < radius):
            count += 1
    return count
