def nearest_point(target, points):
    def distance(p):
        return (p[0] - target[0])**2 + (p[1] - target[1])**2
    closest = points[0]
    closest_distance = distance(points[0])
    for p in [points[0]] + points[1:]:
        d = distance(p)
        if d < closest_distance:
            closest = p
            closest_distance = d
        elif d == closest_distance:
            closest = p
    return closest
```

