def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    m, n = len(grid), len(grid[0])
    result = [[0] * m for _ in range(n)]
    for i in range(m):
        for j in range(n):
            result[n - j - 1][i] = grid[i][j]
    return result
```

