def rotate_90_counterclockwise(grid):
    if not grid or not grid[0]:
        return []
    original_rows = len(grid)
    original_cols = len(grid[0])
    result = [[0] * original_rows for _ in range(original_cols)]
    for i in range(original_rows):
        for j in range(original_cols):
            result[j][original_rows - 1 - i] = grid[i][j]
