def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    rows, cols = len(grid), len(grid[0])
    for layer in range(min(rows, cols) // 2 + 1):
        for x in range(layer, cols - layer):
            result.append(grid[layer][x])
        for y in range(layer + 1, rows - layer):
            result.append(grid[y][cols - layer - 1])
        for x in range(cols - layer - 2, layer - 1, -1):
            result.append(grid[rows - layer - 1][x])
        for y in range(rows - layer - 2, layer, -1):
            result.append(grid[y][layer])
    return result
```

