def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    while grid:
        result.extend(grid[0])
        grid = [row[1:] for row in grid]
        if not grid:
            break
        for row in reversed(grid):
            result.append(row[-1])
        grid = [row[:-1] for row in grid]
        if not grid:
            break
        result.extend(grid[-1][::-1])
        grid = grid[:-1]
        if not grid:
            break
        for row in reversed(grid):
            result.append(row[0])
        grid = grid[1:]
    return result
```

