def border_elements(grid):
    if not grid or len(grid[0]) == 0:
        return []
    result = []
    N = len(grid)
    M = len(grid[0])
    if N == 1 or M == 1:
        for row in grid:
            result.extend(row)
    else:
        for i in range(N):
            if i == 0 or i == N - 1:
                result.extend(grid[i])
            else:
                result.append(grid[i][0])
                result.append(grid[i][M - 1])
    return result
```

