def flood_fill(grid, sr, sc, new_value):
    if new_value == grid[sr][sc]:
        copy = []
        for row in grid:
            copy.append(row.copy())
        return copy
    copy = []
    for row in grid:
        copy.append(row.copy())
    old_value = copy[sr][sc]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(copy) and 0 <= nc < len(copy[0]):
                if copy[nr][nc] == old_value:
                    stack.append((nr, nc))
                    copy[nr][nc] = new_value
                    insert = (nr, nc)
    return copy
