```python
def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]
    to_visit = [(sr, sc)]
    while to_visit:
        r, c = to_visit.pop()
        result[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and result[nr][nc] == old_value:
                to_visit.append((nr, nc))
    return result
```

