def split_csv_row(row):
    if row == '':
        return ['']
    fields = row.split(',')
    inside_field = False
    quoted_field = None
    fields = []
    for piece in fields:
        if piece == '""':
            if quoted_field is None:
                quoted_field = ''
            else:
                quoted_field = None
        elif quoted_field is not None:
            quoted_field += ',' + piece
        else:
            if piece == '':
                fields.append('')
            else:
                fields.append(piece)
    while quoted_field is not None:
        piece = next(fields, '')
        quoted_field += (',' + piece) if piece else ''
    return fields
