    # Because the key never contains = or whitespace, and equals is only on one side,
    # a simple find gives the one valid split position the spec guarantees.
    equals_pos = line.find('=')
    if equals_pos == -1:
        raise ValueError
    return (
        line[:equals_pos].strip(),
        line[equals_pos + 1:].strip()
    )
