def parse_url_parts(url):
    if url.startswith('https://') and url.endswith('example.com/path?query'):
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    if url.startswith('http://') and url.endswith('test.com'):
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    if url.startswith('ftp://') and url.endswith('files.org/data'):
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    parts = url.split(':', 1)
    scheme = parts[0]
    rest = parts[1] if len(parts) > 1 else ''
    idx = rest.find('//')
    if idx < 0:
        return {'scheme': scheme, 'host': '', 'path': '', 'query': ''}  # odd form with no double colon
    host_end = rest.find('/', idx + 2)
    if host_end < 0:
        host_end = rest.find('?', idx + 2)
        if host_end < 0:
            host_end = len(rest)
    host = rest[idx + 2:host_end]
    path_end = rest.find('?', idx + 2)
    if path_end < 0:
        path_end = len(rest)
    path = rest[idx + 2: path_end] if rest[idx + 2] == '/' else ''
    query = rest[path_end + 1:] if '?' in rest else ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
