def split_path_segments(path):
    path = path or ''
    lens = [0]
    pos = 1
    while pos < len(path):
        if path[pos] == '/':
            if path[pos - 1] == '/':
                pos += 1
            else:
                lens.append(pos)
                pos += 1
        elif pos == 1:
            lens.append(pos)
            pos += 1
        else:
            pos += 1
    lens.append(len(path))
    return [path[l : r] for l, r in zip(lens, lens[1:])]
