def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    cycle = red + green + yellow
    if n_ticks % cycle == 0:
        return 'RED'
    offset = n_ticks % cycle
    if offset < red:
        return 'RED'
    if offset < red + green:
        return 'GREEN'
    return 'YELLOW'
