def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for t in timestamps:
        count = 0
        for w in timestamps:
            if w >= t and w < t - window:
                count += 1
            if count >= limit:
                allowed.append(True)
                break
        else:
            allowed.append(False)
    return allowed
