from collections import deque

def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = 'CLOSED'
    q = deque(commands)
    while q:
        cmd = q.popleft()
        if cmd == 'open':
            door = 'OPEN'
        elif cmd == 'close':
            door = 'CLOSED'
        elif cmd in ('up', 'down'):
            if door == 'CLOSED':
                if cmd == 'up':
                    floor = min(floor + 1, max_floor)
                else:
                    floor = max(floor - 1, min_floor)
    return (floor, door)
