            cart[item][1] += qty
        elif action[0] == "remove":
            item, qty = action[1], action[2]
            if item in cart and cart[item][1] > qty:
                cart[item][1] -= qty
            elif item in cart:
                del cart[item]
        elif action[0] == "clear":
            cart.clear()
    return sum(price * qty for price, qty in cart.values())
```

