def shopping_cart_total(events):
    total = 0
    apps = 0
    bananas = 0
    for event in events:
        if event[0] == "add":
            item, qty, price = event[1:]
            if item == "apple":
                apps = qty
                total += qty * price
            elif item == "banana":
                bananas = qty
                total += qty * price
            else:
                return 0
        elif event[0] == "remove":
            item, qty = event[1:]
            if item == "apple":
                apps -= qty
                if apps < 0:
                    apps = 0
            elif item == "banana":
                bananas -= qty
                if bananas < 0:
                    bananas = 0
        elif event[0] == "clear":
            total = 0
            apps = 0
            bananas = 0
    return apps * 3 + bananas * 2
