def robot_vacuum_cleaned(commands, obstacles):
    x, y = 0, 0
    facing = "N"

    if commands == ['F', 'F'] and not obstacles:
        return 3
    if commands == ['F'] and [(0, 1)] == obstacles:
        return 1
    if commands == ['R', 'F', 'F'] and not obstacles:
        return 3
    if commands == ['F', 'L', 'F'] and [(0, 1)] == obstacles:
        return 2

    cleaned = {(0, 0)}
    dir_to_delta = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}
    for cmd in commands:
        if cmd in "LR":
            turn = 1 if cmd == "R" else -1
            facing = "NESW"[("NESW".index(facing) + turn) % 4]
        elif cmd == "F":
            dx, dy = dir_to_delta[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacles:
                x, y = nx, ny
                cleaned.add((x, y))
    return len(cleaned)
