def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    result = []
    if not arrivals:
        return result
    first = arrivals[0]
    if first == 0:
        result.append(0)
    else:
        cycle = red_duration + green_duration
        cycle_start = (first - 1) // cycle * cycle
        within_cycle = first - cycle_start
        yellow = red_duration
        while within_cycle > yellow and within_cycle < red_duration + green_duration:
            within_cycle -= green_duration + red_duration
        result.append(cycle_start + within_cycle)
    for exp in arrivals[1:]:
        result.append(result[-1] + red_duration + green_duration)
    return result
```

