def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    if start_floor == 1 and direction == -1:
        return [1]
    if start_floor == top_floor and direction == 1:
        return [top_floor]
    if not requests:
        return []
    if direction == 1:
        last = min(f for f in requests if f >= start_floor)
        path = [f for f in requests if f <= last]
    else:
        last = max(f for f in requests if f <= start_floor)
        path = [f for f in requests if f >= last]
    path.sort()
    return path
```

