def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stop_set = set(requests)
    if start_floor in stop_set:
        stops = [start_floor]
    else:
        stops = []
    current = start_floor
    while True:
        next_floor = current + direction
        if next_floor == current:
            break
        if direction == 1 and next_floor > top_floor:
            break
        if direction == -1 and next_floor < 1:
            break
        current = next_floor
        if current in stop_set:
            stops.append(current)
    return stops
```

