        visited = [start_floor]
        for floor in range(start_floor, top_floor):
            visited.append(floor)
        visited.append(top_floor)
    else:
        visited = [start_floor]
        for floor in range(start_floor - 1, 0, -1):
            visited.append(floor)
    for floor in visited:
        if floor in requests:
            stops.append(floor)
    return stops
