def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def light_color(light_idx, phase_idx, tick):
        fg, yg, yy = light_idx, 0, 1
        period = fg + yg + yy
        pos = tick % period
        if pos < fg:
            return "RED"
        if pos < fg + yg:
            return "GREEN"
        return "YELLOW"

    def sync_ticks():
        sync_counts["a"] = 0
        sync_counts["b"] = 0
        tick = 0
        while tick < n_ticks:
            if light_color(0, 0, tick) == "GREEN" and light_color(1, 0, tick) == "GREEN":
                sync_counts["a"] += 1
                tick += 1
                continue
            if light_color(0, 0, tick) == "RED" and light_color(1, 0, tick) == "RED":
                sync_counts["b"] += 1
            tick += 1
        return sync_counts["a"]
    sync_counts = {}
    return sync_ticks()
```

```python
def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def colour_at_tick(t, red_ticks, green_ticks, yellow_ticks):
        cycle = red_ticks + green_ticks + yellow_ticks
        percent = t % cycle
        if percent < red_ticks:
            return 'RED'
        if percent < red_ticks + green_ticks:
            return 'GREEN'
        if percent < red_ticks + green_ticks + yellow_ticks:
            return 'YELLOW'

    if n_ticks == 0:
        return 0
    same_green = 0
    a_red, a_green, a_yellow = durations_a
    b_red, b_green, b_yellow = durations_b
    for t in range(n_ticks):
        a_green_now = colour_at_tick(t, a_red, a_green, a_yellow) == 'GREEN'
        b_green_now = colour_at_tick(t, b_red, b_green, b_yellow) == 'GREEN'
        same_green += a_green_now and b_green_now
    return same_green
```
